// Light Runner – minimal canvas game
// Canvas element with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  // ----- Game state -----
  const player = { x: canvas.width / 2, y: canvas.height / 2, r: 10, speed: 3 };
  let score = 0;
  let gameOver = false;

  // simple light radius (visual only)
  const LIGHT_RADIUS = 120;

  // spawn helpers
  const randPos = (margin = 20) => ({
    x: Math.random() * (canvas.width - 2 * margin) + margin,
    y: Math.random() * (canvas.height - 2 * margin) + margin,
  });

  const crystals = Array.from({ length: 15 }, () => ({ ...randPos(), r: 5 }));
  const enemies = Array.from({ length: 5 }, () => ({ ...randPos(), r: 12 }));

  // ----- Input -----
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function update() {
    if (gameOver) return;
    // movement
    if (keys.ArrowUp) player.y -= player.speed;
    if (keys.ArrowDown) player.y += player.speed;
    if (keys.ArrowLeft) player.x -= player.speed;
    if (keys.ArrowRight) player.x += player.speed;
    // keep inside canvas
    player.x = Math.max(player.r, Math.min(canvas.width - player.r, player.x));
    player.y = Math.max(player.r, Math.min(canvas.height - player.r, player.y));

    // collect crystals
    for (let i = crystals.length - 1; i >= 0; i--) {
      const c = crystals[i];
      const d = Math.hypot(player.x - c.x, player.y - c.y);
      if (d < player.r + c.r) {
        crystals.splice(i, 1);
        score++;
      }
    }
    // collision with enemies – game over
    for (const e of enemies) {
      const d = Math.hypot(player.x - e.x, player.y - e.y);
      if (d < player.r + e.r) {
        gameOver = true;
        break;
      }
    }
  }

  function draw() {
    // dark background
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // light effect around the player
    const gradient = ctx.createRadialGradient(
      player.x, player.y, 0,
      player.x, player.y, LIGHT_RADIUS
    );
    gradient.addColorStop(0, 'rgba(255,255,200,0.8)');
    gradient.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // draw crystals
    ctx.fillStyle = '#0ff';
    crystals.forEach(c => {
      ctx.beginPath();
      ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
      ctx.fill();
    });

    // draw enemies
    ctx.fillStyle = '#f44';
    enemies.forEach(e => {
      ctx.beginPath();
      ctx.arc(e.x, e.y, e.r, 0, Math.PI * 2);
      ctx.fill();
    });

    // draw player (glowing orb)
    ctx.fillStyle = '#ff0';
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.r, 0, Math.PI * 2);
    ctx.fill();

    // UI – score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 20, 30);

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // start on load
  window.addEventListener('load', () => requestAnimationFrame(loop));
})();
